// Executed with an isolated runtime socket and real Pi APIs on either backend.
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
const root = process.env.WI_TEST_PI_PACKAGE;
const cwd = process.env.WI_WORKSPACE_REMOTE_CWD;
const { loadExtensions } = await import(pathToFileURL(`${root}/dist/core/extensions/loader.js`));
const loaded = await loadExtensions([process.env.WI_TEST_EXECUTOR_EXTENSION], process.cwd());
assert.deepEqual(loaded.errors, []);
const extension = loaded.extensions[0];
const context = { cwd: process.cwd(), model: undefined, sessionManager: {getSessionId: () => 'executor-test', getSessionFile: () => undefined} };
const execute = (name, params, signal, update) => extension.tools.get(name).definition.execute(`test-${name}`, params, signal, update, context);
await execute('write', {path: `${cwd}/test.txt`, content: 'first\n'});
await execute('edit', {path: `${cwd}/test.txt`, edits: [{oldText: 'first', newText: 'second'}]});
const read = await execute('read', {path: `${cwd}/test.txt`});
assert.match(JSON.stringify(read.content), /second/);
const list = await execute('ls', {path: cwd});
assert.match(JSON.stringify(list.content), /test.txt/);
const found = await execute('find', {pattern: '*.txt'});
assert.match(JSON.stringify(found.content), /test.txt/);
const missing = await execute('find', {pattern: '*.does-not-exist'});
assert.equal(missing.isError, undefined);
await execute('bash', {command: 'ln -s test.txt link.txt'});
await assert.rejects(execute('write', {path: `${cwd}/link.txt`, content: 'overwritten'}), /symlink/);
await assert.rejects(execute('write', {path: `${cwd}/test.txt`, content: 'INCOMPLETE_WRITE_SENTINEL'}), /Incomplete write/);
const unchanged = await execute('read', {path: `${cwd}/test.txt`});
assert.match(JSON.stringify(unchanged.content), /second/);
const grep = await execute('grep', {pattern: 'second'});
assert.match(JSON.stringify(grep.content), /second/);
let updated = false;
const result = await execute('bash', {command: 'printf first; sleep 1; printf last'}, undefined, () => {updated = true;});
assert.equal(updated, true);
assert.match(JSON.stringify(result.content), /firstlast/);
const [userBash] = extension.handlers.get('user_bash');
const operations = (await userBash({}, context)).operations;
let output = '';
const shell = await operations.exec('pwd', process.cwd(), {onData: chunk => {output += chunk;}});
assert.equal(shell.exitCode, 0);
assert.equal(output.trim(), cwd);
const controller = new AbortController();
setTimeout(() => controller.abort(), 200);
await assert.rejects(operations.exec('sleep 60', process.cwd(), {signal: controller.signal, onData() {}}), /aborted/);
await execute('write', {path: `${cwd}/AGENTS.md`, content: 'EXECUTOR_CONTEXT_SENTINEL'});
const [before] = extension.handlers.get('before_agent_start');
const prompt = await before({systemPrompt: `Current working directory: ${process.cwd()}`}, context);
assert.match(prompt.systemPrompt, /EXECUTOR_CONTEXT_SENTINEL/);
assert.ok(prompt.systemPrompt.includes(`Current working directory: ${cwd}`));
console.log('Pi read/write/edit/ls/find/grep/bash, streaming, abort, ! routing and context passed');
